CREATE TABLE IF NOT EXISTS users ( username TEXT PRIMARY KEY, lname TEXT UNIQUE NOT NULL, pw_hash TEXT NOT NULL, salt TEXT NOT NULL, rating INTEGER NOT NULL DEFAULT 1200, peak INTEGER NOT NULL DEFAULT 1200, games INTEGER NOT NULL DEFAULT 0, wins INTEGER NOT NULL DEFAULT 0, losses INTEGER NOT NULL DEFAULT 0, draws INTEGER NOT NULL DEFAULT 0, created DOUBLE PRECISION NOT NULL, last_seen DOUBLE PRECISION NOT NULL );
CREATE TABLE IF NOT EXISTS ratings ( username TEXT NOT NULL, game TEXT NOT NULL, rating INTEGER NOT NULL DEFAULT 1200, peak INTEGER NOT NULL DEFAULT 1200, games INTEGER NOT NULL DEFAULT 0, wins INTEGER NOT NULL DEFAULT 0, losses INTEGER NOT NULL DEFAULT 0, draws INTEGER NOT NULL DEFAULT 0, PRIMARY KEY (username, game) );
CREATE TABLE IF NOT EXISTS rooms ( id TEXT PRIMARY KEY, white TEXT, black TEXT, white_guest INTEGER NOT NULL DEFAULT 0, black_guest INTEGER NOT NULL DEFAULT 0, state TEXT NOT NULL, status TEXT NOT NULL, rated INTEGER NOT NULL DEFAULT 1, private INTEGER NOT NULL DEFAULT 0, tc INTEGER NOT NULL DEFAULT 0, clock_w DOUBLE PRECISION NOT NULL DEFAULT 0, clock_b DOUBLE PRECISION NOT NULL DEFAULT 0, last_ts DOUBLE PRECISION NOT NULL DEFAULT 0, version INTEGER NOT NULL DEFAULT 0, created DOUBLE PRECISION NOT NULL, updated DOUBLE PRECISION NOT NULL );
CREATE TABLE IF NOT EXISTS games ( id TEXT PRIMARY KEY, mode TEXT NOT NULL, white TEXT NOT NULL, black TEXT NOT NULL, result TEXT NOT NULL, reason TEXT, score_w INTEGER NOT NULL, score_b INTEGER NOT NULL, moves TEXT NOT NULL, rating_w INTEGER, rating_b INTEGER, delta_w INTEGER, delta_b INTEGER, created DOUBLE PRECISION NOT NULL );
CREATE TABLE IF NOT EXISTS chat ( id TEXT PRIMARY KEY, room TEXT NOT NULL, author TEXT NOT NULL, body TEXT NOT NULL, ts DOUBLE PRECISION NOT NULL );
CREATE TABLE IF NOT EXISTS presence ( name TEXT PRIMARY KEY, ts DOUBLE PRECISION NOT NULL );
CREATE TABLE IF NOT EXISTS wallet ( username TEXT PRIMARY KEY, attempts INTEGER NOT NULL DEFAULT 0, points INTEGER NOT NULL DEFAULT 0, earned INTEGER NOT NULL DEFAULT 0, paid_total INTEGER NOT NULL DEFAULT 0, champ_wins INTEGER NOT NULL DEFAULT 0, champ_losses INTEGER NOT NULL DEFAULT 0 );
CREATE TABLE IF NOT EXISTS payments ( id TEXT PRIMARY KEY, username TEXT NOT NULL, amount INTEGER NOT NULL, attempts INTEGER NOT NULL, receipt TEXT, image TEXT, status TEXT NOT NULL, admin TEXT, note TEXT, created DOUBLE PRECISION NOT NULL, decided DOUBLE PRECISION );
CREATE TABLE IF NOT EXISTS withdrawals ( id TEXT PRIMARY KEY, username TEXT NOT NULL, points INTEGER NOT NULL, amount INTEGER NOT NULL, phone TEXT NOT NULL, status TEXT NOT NULL, admin TEXT, created DOUBLE PRECISION NOT NULL, decided DOUBLE PRECISION );
CREATE TABLE IF NOT EXISTS champ_games ( id TEXT PRIMARY KEY, username TEXT NOT NULL, game TEXT NOT NULL, level TEXT NOT NULL, status TEXT NOT NULL, result TEXT, points INTEGER NOT NULL DEFAULT 0, created DOUBLE PRECISION NOT NULL, finished DOUBLE PRECISION );
CREATE TABLE IF NOT EXISTS horses ( username TEXT PRIMARY KEY, burst DOUBLE PRECISION NOT NULL DEFAULT 1, speed DOUBLE PRECISION NOT NULL DEFAULT 1, stamina DOUBLE PRECISION NOT NULL DEFAULT 1, reverse DOUBLE PRECISION NOT NULL DEFAULT 1, bonus INTEGER NOT NULL DEFAULT 0, upgrades INTEGER NOT NULL DEFAULT 0 );
CREATE TABLE IF NOT EXISTS settings ( key TEXT PRIMARY KEY, value TEXT NOT NULL );
CREATE INDEX IF NOT EXISTS idx_games_white ON games(white);
CREATE INDEX IF NOT EXISTS idx_games_black ON games(black);
CREATE INDEX IF NOT EXISTS idx_chat_room ON chat(room);
CREATE INDEX IF NOT EXISTS idx_rooms_status ON rooms(status);
CREATE INDEX IF NOT EXISTS idx_ratings_game ON ratings(game, rating);
CREATE INDEX IF NOT EXISTS idx_payments_status ON payments(status);
CREATE INDEX IF NOT EXISTS idx_withdrawals_status ON withdrawals(status);
ALTER TABLE games ADD COLUMN IF NOT EXISTS game TEXT NOT NULL DEFAULT 'togyz';
ALTER TABLE rooms ADD COLUMN IF NOT EXISTS game TEXT NOT NULL DEFAULT 'togyz';
ALTER TABLE payments ADD COLUMN IF NOT EXISTS kind TEXT NOT NULL DEFAULT 'attempts';
ALTER TABLE payments ADD COLUMN IF NOT EXISTS qty INTEGER NOT NULL DEFAULT 1;
ALTER TABLE horses ADD COLUMN IF NOT EXISTS t_speed DOUBLE PRECISION NOT NULL DEFAULT 1;
ALTER TABLE horses ADD COLUMN IF NOT EXISTS t_stamina DOUBLE PRECISION NOT NULL DEFAULT 1;
ALTER TABLE horses ADD COLUMN IF NOT EXISTS t_accuracy DOUBLE PRECISION NOT NULL DEFAULT 1;
ALTER TABLE horses ADD COLUMN IF NOT EXISTS t_bonus INTEGER NOT NULL DEFAULT 0;
